async function availablePort(){const server=net.createServer();await new Promise(r=>server.listen(0,'127.0.0.1',r));const port=server.address().port;await new Promise(r=>server.close(r));return port;}
before(async()=>{await mkdir(resolve(root,'cloudflare/work'),{recursive:true});temp=await mkdtemp(resolve(root,'cloudflare/work/test-'));converterPort=await availablePort();converter=spawn(resolve(root,'.venv/bin/python'),[resolve(root,'cloudflare/converter/server.py')],{cwd:root,env:{...process.env,PYTHONDONTWRITEBYTECODE:'1',INKBOUND_CONVERTER_ROOT:root,CONVERTER_BIND:'127.0.0.1',CONVERTER_PORT:String(converterPort)},stdio:['ignore','ignore','pipe']});let errors='';converter.stderr.on('data',b=>errors+=b);let ready=false;for(let n=0;n<100;++n){try{ready=(await fetch(`http://127.0.0.1:${converterPort}/ready`)).ok;if(ready)break;}catch{}await new Promise(r=>setTimeout(r,50));}assert.ok(ready,'real isolated Python converter HTTP adapter starts '+errors);
 mf=new Miniflare(convertV4MiniflareOptions({d1Persist:resolve(temp,'d1'),r2Persist:resolve(temp,'r2'),workers:[
 {name:'main',modulesRoot:resolve(root,'cloudflare'),modules:[{type:'ESModule',path:resolve(root,'cloudflare/src/worker.mjs')},{type:'ESModule',path:resolve(root,'cloudflare/src/reference_table.mjs')},{type:'ESModule',path:resolve(root,'cloudflare/src/illustrations.mjs')},{type:'ESModule',path:resolve(root,'cloudflare/src/auto_reply.mjs')},{type:'ESModule',path:resolve(root,'cloudflare/src/visual_scene.mjs')},{type:'ESModule',path:resolve(root,'cloudflare/src/visual_references.mjs')},{type:'ESModule',path:resolve(root,'cloudflare/src/visual_reference_data.mjs')},{type:'ESModule',path:resolve(root,'cloudflare/src/visual_sources.mjs')},{type:'ESModule',path:resolve(root,'cloudflare/src/image_sizes.mjs')},{type:'ESModule',path:resolve(root,'cloudflare/src/visual_quality.mjs')},{type:'ESModule',path:resolve(root,'cloudflare/src/visual_review.mjs')},{type:'ESModule',path:resolve(root,'cloudflare/src/composition_plan.mjs')},{type:'ESModule',path:resolve(root,'cloudflare/src/picture_plan.mjs')},{type:'ESModule',path:resolve(root,'cloudflare/src/picture_review.mjs')}],compatibilityDate:'2026-09-13',compatibilityFlags:['nodejs_compat'],d1Databases:['DB'],r2Buckets:['UPLOADS'],queueProducers:{WORK:'work'},queueConsumers:{work:{maxBatchSize:1,maxBatchTimeout:0}},bindings:{APP_ORIGIN:origin,ALLOW_LOCAL_HTTP:'true',DOWNLOAD_SECRET:'synthetic-test-signing-material-32-bytes',OPENAI_API_KEY:'',TOM_MODELS:'gpt-5.4-mini',CONVERSION_ENABLED:'true',TOM_ENABLED:'false'},serviceBindings:{ASSETS:()=>new Response('synthetic assets'),CONVERTER:'converter'}},
 // Preserve streaming across the actual workerd HTTP boundary. Buffering into a
 // Node Buffer here would hide Workers' fixed-length versus chunked semantics.
 // The response identity stream mirrors loss of known-length metadata across
 // the container service boundary and exercises R2's known-length requirement.
 {name:'converter',modules:true,compatibilityDate:'2026-09-13',script:`export default {async fetch(request){const response=await fetch('http://127.0.0.1:${converterPort}/convert',{method:'POST',headers:request.headers,body:request.body});return new Response(response.body.pipeThrough(new IdentityTransformStream()),response);}}`}
 ]}));db=await mf.getD1Database('DB');bucket=await mf.getR2Bucket('UPLOADS');for(const file of (await readdir(resolve(root,'cloudflare/migrations'))).filter(f=>f.endsWith('.sql')).sort())await db.exec(await readFile(resolve(root,'cloudflare/migrations',file),'utf8'));retainedFailure=false;});
after(async()=>{await mf?.dispose();if(converter){converter.kill('SIGTERM');await new Promise(r=>converter.once('exit',r));}if(!retainedFailure)await rm(temp,{recursive:true,force:true});else console.error('FAILED_COMPANION_FIXTURE_RETAINED '+temp);});
class Client{constructor(token=''){this.ip='192.0.2.'+nextIP++;this.token=token;this.cookie='';this.csrf='';}async call(method,path,data,raw,headers={},expected=200){const h={'CF-Connecting-IP':this.ip,...headers};if(this.token)h.Authorization='Bearer '+this.token;if(this.cookie)h.Cookie=this.cookie;if(method!=='GET'){h.Origin=origin;h['X-CSRF-Token']=this.csrf;}if(data!==undefined)h['Content-Type']='application/json';Object.assign(h,headers);const response=await mf.dispatchFetch(origin+path,{method,headers:h,body:raw??(data!==undefined?JSON.stringify(data):undefined)});const result=response.headers.get('content-type')?.includes('application/json')?await response.json():new Uint8Array(await response.arrayBuffer());if(expected!==null)assert.equal(response.status,expected,`${method} ${path}: ${JSON.stringify(result)}`);const cookie=response.headers.get('set-cookie');if(cookie)this.cookie=cookie.split(';')[0];if(result.csrf)this.csrf=result.csrf;return {result,status:response.status,headers:response.headers};}}
async function account(email){const id=randomUUID(),salt='a'.repeat(32),key=scryptSync('synthetic-test-password-123',Buffer.from(salt,'hex'),64,{N:16384,r:8,p:1}).toString('hex');await db.prepare('INSERT INTO users VALUES(?,?,?)').bind(id,email,salt+':'+key).run();const browser=new Client();await browser.call('POST','/v1/auth/login',{email,password:'synthetic-test-password-123'});browser.user=id;return browser;}
async function pair(browser){const native=new Client(),start=(await native.call('POST','/v1/pair/start',{name:'Synthetic reader'},undefined,{},201)).result;native.token=start.pairing_token;await browser.call('POST','/v1/pair/claim',{code:start.code});const shown=(await native.call('GET','/v1/pair/'+start.pairing_id)).result;assert.equal(shown.state,'claimed');const approved=(await native.call('POST',`/v1/pair/${start.pairing_id}/approve`,{approve:true},undefined,{},201)).result;await native.call('POST',`/v1/pair/${start.pairing_id}/approve`,{approve:true},undefined,{},409);const device=new Client(approved.device_token);device.id=approved.device_id;return device;}
async function upload(browser,device,name,bytes,newImport=false){const j=(await browser.call('POST','/v1/jobs',{device_id:device.id,filename:name,size:bytes.length,sha256:digest(bytes),new_import:newImport},undefined,{},201)).result;const headers={'Content-Type':'application/octet-stream','Content-Range':`bytes 0-${bytes.length-1}/${bytes.length}`};await browser.call('PUT',`/v1/jobs/${j.job_id}/chunk`,undefined,bytes,headers);const replay=await browser.call('PUT',`/v1/jobs/${j.job_id}/chunk`,undefined,bytes,headers);assert.equal(replay.result.replayed,true);await browser.call('POST',`/v1/jobs/${j.job_id}/complete`,{});let last;const began=Date.now(),deadline=began+65000;/* processJob has a 60-second converter budget; allow the 1-second queue batch and status publication. The earlier 200x25ms window falsely failed a correctly rejected PDF at 14.7s; those failure logs are retained. */while(Date.now()<deadline){const ready=(await browser.call('GET','/v1/jobs/'+j.job_id)).result;last=ready;if(['waiting for device','failed'].includes(ready.status))return ready;await new Promise(r=>setTimeout(r,250));}const missed={format:last?.source_format,status:last?.status,error:last?.error,elapsed_ms:Date.now()-began};let later=last;const observeUntil=Date.now()+35000;while(later?.status==='processing'&&Date.now()<observeUntil){await new Promise(r=>setTimeout(r,250));later=(await browser.call('GET','/v1/jobs/'+j.job_id)).result;}throw Error('conversion did not finish '+JSON.stringify({...missed,later_status:later?.status,later_error:later?.error,later_elapsed_ms:Date.now()-began}));}
test('a reader can revoke its own pairing; its credential then stops working and the owner sees it revoked',async()=>{const browser=await account('unpair@example.invalid'),device=await pair(browser);await device.call('GET','/v1/device/jobs');assert.equal((await device.call('POST','/v1/device/revoke',{})).result.revoked,true);await device.call('GET','/v1/device/jobs',undefined,undefined,{},401);await device.call('POST','/v1/device/revoke',{},undefined,{},401);const listed=(await browser.call('GET','/v1/devices')).result.devices;assert.equal(listed.length,1);assert.equal(listed[0].revoked,1);});
test('real workerd+D1+R2+queue+isolated converter: auth, pairing, upload, delivery, tombstones',async()=>{const browser=await account('owner@example.invalid'),other=await account('other@example.invalid'),device=await pair(browser);assert.equal((await browser.call('GET','/v1/me')).result.protocol,1);await other.call('DELETE','/v1/devices/'+device.id,undefined,undefined,{},404);await browser.call('POST','/v1/jobs',{},undefined,{'X-CSRF-Token':'bad'},403);await browser.call('POST','/v1/jobs',{},undefined,{Origin:'https://evil.invalid'},403);const bytes=Buffer.from('A real synthetic document.\n\nRendered as an EPUB by the real converter.');const job=await upload(browser,device,'synthetic.txt',bytes);assert.equal(job.status,'waiting for device',job.error);assert.equal(job.format,'epub');assert.equal(job.converted,1);await other.call('GET','/v1/jobs/'+job.id,undefined,undefined,{},404);const manifest=(await device.call('GET','/v1/device/jobs')).result.jobs[0];assert.equal(manifest.intentional_new,false);await device.call('GET',`/v1/device/jobs/${job.id}/content`,undefined,undefined,{},403);const delivered=await device.call('GET',`/v1/device/jobs/${job.id}/content`,undefined,undefined,{'X-Download-Token':manifest.download_token});assert.equal(digest(delivered.result),manifest.sha256);const part=await device.call('GET',`/v1/device/jobs/${job.id}/content`,undefined,undefined,{'X-Download-Token':manifest.download_token,Range:'bytes=0-15'},206);assert.deepEqual(part.result,delivered.result.slice(0,16));await device.call('POST',`/v1/device/jobs/${job.id}/ack`,{document_id:manifest.document_id,sha256:manifest.sha256,durable:false},undefined,{},409);const ack={document_id:manifest.document_id,sha256:manifest.sha256,durable:true};await device.call('POST',`/v1/device/jobs/${job.id}/ack`,ack);await device.call('POST',`/v1/device/jobs/${job.id}/ack`,ack);assert.equal((await bucket.list({prefix:`jobs/${job.id}/`})).objects.length,0);await browser.call('DELETE','/v1/jobs/'+job.id,undefined,undefined,{},409);await device.call('POST','/v1/device/tombstones',{document_id:manifest.document_id});await browser.call('DELETE','/v1/jobs/'+job.id,undefined,undefined,{},409);await device.call('POST',`/v1/device/jobs/${job.id}/ack`,ack,undefined,{},409);await browser.call('POST','/v1/jobs',{device_id:device.id,filename:'synthetic.txt',size:bytes.length,sha256:digest(bytes)},undefined,{},409);const intentional=await upload(browser,device,'synthetic.txt',bytes,true);assert.notEqual(intentional.document_id,manifest.document_id);assert.equal((await device.call('GET','/v1/device/jobs')).result.jobs[0].intentional_new,true);await browser.call('DELETE','/v1/devices/'+device.id);await device.call('GET','/v1/device/jobs',undefined,undefined,{},401);});
test('malformed native document rejected; checksum mismatch cannot be delivered',async()=>{const browser=await account('format@example.invalid'),device=await pair(browser),job=await upload(browser,device,'bad.pdf',Buffer.from('not a PDF'));assert.equal(job.status,'failed');assert.match(job.error,/PDF signature mismatch/);const bytes=Buffer.from('hello'),j=(await browser.call('POST','/v1/jobs',{device_id:device.id,filename:'bad.txt',size:bytes.length,sha256:'b'.repeat(64)},undefined,{},201)).result;await browser.call('PUT',`/v1/jobs/${j.job_id}/chunk`,undefined,bytes,{'Content-Type':'application/octet-stream','Content-Range':'bytes 0-4/5'});await browser.call('POST',`/v1/jobs/${j.job_id}/complete`,{});for(let i=0;i<100;++i){const ready=(await browser.call('GET','/v1/jobs/'+j.job_id)).result;if(ready.status==='failed')return;await new Promise(r=>setTimeout(r,25));}assert.fail('checksum mismatch must fail');});
test('Tom construction: scopes, no-context privacy, inline handwriting, real SSE simulation',async()=>{const general={request_id:randomUUID(),conversation_id:randomUUID(),scope:'general',question:'Question',context:null,history:[],consent:true,provider:'openai',max_output_tokens:2048,model:'gpt-5.4-mini'};assert.equal(providerPayload(validateTom(general,['gpt-5.4-mini'])).tools.length,0);for(const scope of ['word','sentences','paragraphs','page']){const d=validateTom({...general,scope,context:{document_id:randomUUID(),revision:'revision',anchor:{page:1},text:'selected source only',page_kind:'pdf-source-page'}},['gpt-5.4-mini']);assert.equal(d.scope,scope);}assert.throws(()=>validateTom({...general,context:{text:'private'}},['gpt-5.4-mini']));assert.throws(()=>validateTom({...general,page_image:'https://private.invalid/image'},['gpt-5.4-mini']));assert.throws(()=>validateTom({...general,tools:[{name:'shell'}]},['gpt-5.4-mini']));const browser=await account('tom@example.invalid');await browser.call('POST','/v1/tom/requests',general,undefined,{},503);
 // The fake provider is injected only into this Node-side processor test; all
 // actual persistence bindings are Miniflare D1/R2. No paid network call occurs.
 const env={DB:db,UPLOADS:bucket,TOM_ENABLED:'true',OPENAI_API_KEY:'synthetic',TOM_MODELS:'gpt-5.4-mini'};const serialized=JSON.stringify(general),key=`tom/${general.request_id}/synthetic.json`;await bucket.put(key,serialized);await db.prepare("INSERT INTO tom(id,user_id,conversation_id,fingerprint,payload,payload_key,status,created,updated) VALUES(?,?,?,?,?,?,'queued',?,?)").bind(general.request_id,browser.user,general.conversation_id,digest(serialized),serialized,key,Date.now()/1000,Date.now()/1000).run();const savedFetch=globalThis.fetch;try{globalThis.fetch=async(url,init)=>{providerCalls++;assert.equal(url,'https://api.openai.com/v1/responses');assert.equal(JSON.parse(init.body).store,false);return new Response('data: '+JSON.stringify({type:'response.output_text.delta',delta:'Actual partial answer'})+'\r\n\r\ndata: '+JSON.stringify({type:'response.completed'})+'\r\n\r\n',{headers:{'Content-Type':'text/event-stream'}});};await processTom(env,general.request_id);await processTom(env,general.request_id);}finally{globalThis.fetch=savedFetch;}assert.equal(providerCalls,1,'redelivered queue job cannot send duplicate provider request');const row=await db.prepare('SELECT status,text FROM tom WHERE id=?').bind(general.request_id).first();assert.equal(row.status,'completed');assert.equal(row.text,'Actual partial answer');const events=await db.prepare('SELECT * FROM tom_events WHERE request_id=? ORDER BY seq').bind(general.request_id).all();assert.ok(events.results.some(e=>e.event==='delta'));});
test('expired tickets and bounded external inputs reject',()=>{const env={DOWNLOAD_SECRET:'synthetic-test-signing-material-32-bytes'},j={id:randomUUID(),sha256:'a'.repeat(64)};assert.notEqual(downloadTicket(env,j,'one',123),downloadTicket(env,j,'two',123));assert.throws(()=>downloadTicket({DOWNLOAD_SECRET:''},j,'one'));});

test('PDF, EPUB, DOCX and Markdown through real converter and private R2 delivery',async()=>{const browser=await account('allformats@example.invalid'),device=await pair(browser);const fixtures=JSON.parse(execFileSync(resolve(root,'.venv/bin/python'),['-c','import json,base64;from tests.fixtures import pdf,epub,docx;print(json.dumps({k:base64.b64encode(f()).decode() for k,f in [("pdf",pdf),("epub",epub),("docx",docx)]}))'],{cwd:root,env:{...process.env,PYTHONDONTWRITEBYTECODE:'1'}}));fixtures.md=Buffer.from('# A heading\n\n**A synthetic note**').toString('base64');for(const [format,encoded]of Object.entries(fixtures)){const source=Buffer.from(encoded,'base64'),job=await upload(browser,device,'fixture.'+format,source);assert.equal(job.status,'waiting for device',format+': '+job.error);assert.equal(job.format,format==='pdf'?'pdf':'epub');const manifest=(await device.call('GET','/v1/device/jobs')).result.jobs.find(j=>j.job_id===job.id);const delivered=await device.call('GET',`/v1/device/jobs/${job.id}/content`,undefined,undefined,{'X-Download-Token':manifest.download_token});assert.equal(digest(delivered.result),manifest.sha256);/* the reader requires this exact ETag on every range reply */assert.equal(delivered.headers.get('etag'),`"${manifest.sha256}"`);const piece=await device.call('GET',`/v1/device/jobs/${job.id}/content`,undefined,undefined,{'X-Download-Token':manifest.download_token,Range:'bytes=0-9'},206);assert.equal(piece.headers.get('etag'),`"${manifest.sha256}"`);assert.equal(piece.headers.get('content-range'),`bytes 0-9/${manifest.size}`);await device.call('POST',`/v1/device/jobs/${job.id}/ack`,{durable:true,document_id:manifest.document_id,sha256:manifest.sha256});}});
test('concurrent conflicting chunks cannot overwrite the acknowledged bytes; partial resume works',async()=>{const browser=await account('chunks@example.invalid'),device=await pair(browser),data=Buffer.from('AAAABBBB'),job=(await browser.call('POST','/v1/jobs',{device_id:device.id,filename:'partial.txt',size:data.length,sha256:digest(data)},undefined,{},201)).result;const headers={'Content-Type':'application/octet-stream','Content-Range':'bytes 0-3/8'};const results=await Promise.all([browser.call('PUT',`/v1/jobs/${job.job_id}/chunk`,undefined,Buffer.from('AAAA'),headers,null),browser.call('PUT',`/v1/jobs/${job.job_id}/chunk`,undefined,Buffer.from('CCCC'),headers,null)]);assert.deepEqual(results.map(r=>r.status).sort(),[200,409]);const stored=await db.prepare('SELECT * FROM chunks WHERE job_id=?').bind(job.job_id).first();const content=await bucket.get(stored.object_key);assert.equal(digest(new Uint8Array(await content.arrayBuffer())),stored.sha256);await browser.call('PUT',`/v1/jobs/${job.job_id}/chunk`,undefined,Buffer.from('BBBB'),{'Content-Type':'application/octet-stream','Content-Range':'bytes 4-7/8'});assert.equal((await browser.call('GET','/v1/jobs/'+job.job_id)).result.received,8);await browser.call('DELETE','/v1/jobs/'+job.job_id);assert.equal((await bucket.list({prefix:`jobs/${job.job_id}/`})).objects.length,0);});
test('Tom HTTP state records one paid-operation identity, enforces storage quota and preserves disconnects',async()=>{const browser=await account('tomstates@example.invalid'),work=[];const env={DB:db,UPLOADS:bucket,APP_ORIGIN:origin,ALLOW_LOCAL_HTTP:'true',TOM_MODELS:'gpt-5.4-mini',TOM_ENABLED:'true',OPENAI_API_KEY:'synthetic',WORK:{async send(value){work.push(value);}}};const data={request_id:randomUUID(),conversation_id:randomUUID(),scope:'general',question:'A second synthetic question',context:null,history:[],consent:true,provider:'openai',max_output_tokens:2048,model:'gpt-5.4-mini'};const send=body=>route(new Request(origin+'/v1/tom/requests',{method:'POST',headers:{Origin:origin,Cookie:browser.cookie,'X-CSRF-Token':browser.csrf,'Content-Type':'application/json'},body:JSON.stringify(body)}),env,{});assert.equal((await send(data)).status,202);assert.equal((await (await send(data)).json()).replayed,true);assert.equal(work.length,1);await assert.rejects(send({...data,question:'altered'}),/conflicts/);const savedFetch=globalThis.fetch;try{globalThis.fetch=async()=>new Response('data: '+JSON.stringify({type:'response.output_text.delta',delta:'A genuine partial'})+'\n\n');await processTom(env,data.request_id);}finally{globalThis.fetch=savedFetch;}const row=await db.prepare('SELECT status,text,error FROM tom WHERE id=?').bind(data.request_id).first();assert.equal(row.status,'interrupted');assert.equal(row.text,'A genuine partial');assert.match(row.error,/Explicit retry/);await db.prepare('UPDATE tom SET payload_size=? WHERE id=?').bind(67108864,data.request_id).run();await assert.rejects(send({...data,request_id:randomUUID()}),/quota/);});
test('sweeper completes durable cleanup bookkeeping without starving newer terminal jobs',async()=>{const browser=await account('cleanup@example.invalid'),device=await pair(browser);const job=(await browser.call('POST','/v1/jobs',{device_id:device.id,filename:'retention.txt',size:1,sha256:digest('x')},undefined,{},201)).result;await bucket.put(`jobs/${job.job_id}/orphan`,'synthetic');await db.prepare("UPDATE jobs SET status='imported',cleanup_pending=1 WHERE id=?").bind(job.job_id).run();await sweep({DB:db,UPLOADS:bucket,WORK:{async send(){}}});assert.equal((await bucket.list({prefix:`jobs/${job.job_id}/`})).objects.length,0);assert.equal((await db.prepare('SELECT cleanup_pending FROM jobs WHERE id=?').bind(job.job_id).first()).cleanup_pending,0);});

function localEnv(extra={}){return {DB:db,UPLOADS:bucket,APP_ORIGIN:origin,ALLOW_LOCAL_HTTP:'true',TOM_MODELS:'gpt-5.4-mini',TOM_ENABLED:'true',OPENAI_API_KEY:'synthetic',WORK:{async send(){}},...extra};}
function directRequest(browser,method,path,data){return new Request(origin+path,{method,headers:{Origin:origin,Cookie:browser.cookie,'X-CSRF-Token':browser.csrf,'Content-Type':'application/json','CF-Connecting-IP':browser.ip},...(data===undefined?{}:{body:JSON.stringify(data)})});}
function bucketWith(overrides){return new Proxy(bucket,{get(target,key){if(key in overrides)return overrides[key];const value=Reflect.get(target,key);return typeof value==='function'?value.bind(target):value;}});}

test('cancel racing an in-flight R2 chunk write leaves no private relay bytes',async()=>{
 const browser=await account('cancel-race@example.invalid'),device=await pair(browser),bytes=Buffer.from('late upload'),job=(await browser.call('POST','/v1/jobs',{device_id:device.id,filename:'race.txt',size:bytes.length,sha256:digest(bytes)},undefined,{},201)).result;
 const env=localEnv({UPLOADS:bucketWith({async put(key,value,options){await browser.call('DELETE','/v1/jobs/'+job.job_id);return bucket.put(key,value,options);}})});
 const request=new Request(origin+`/v1/jobs/${job.job_id}/chunk`,{method:'PUT',headers:{Origin:origin,Cookie:browser.cookie,'X-CSRF-Token':browser.csrf,'Content-Type':'application/octet-stream','Content-Range':`bytes 0-${bytes.length-1}/${bytes.length}`},body:bytes});
 await assert.rejects(route(request,env,{}),/Concurrent chunk/);
 assert.equal((await bucket.list({prefix:`jobs/${job.job_id}/`})).objects.length,0,'late rejected upload must not survive completed cancellation cleanup');
});

test('concurrent conflicting Tom request identities do not leave losing private payloads',async()=>{
 const browser=await account('tom-race@example.invalid'),data={request_id:randomUUID(),conversation_id:randomUUID(),scope:'general',question:'First',context:null,history:[],consent:true,provider:'openai',max_output_tokens:2048,model:'gpt-5.4-mini'};
 let arrivals=0,release;const barrier=new Promise(r=>release=r);const env=localEnv({UPLOADS:bucketWith({async put(key,value,options){const result=await bucket.put(key,value,options);if(++arrivals===2)release();await barrier;return result;}})});
 const results=await Promise.allSettled([route(directRequest(browser,'POST','/v1/tom/requests',data),env,{}),route(directRequest(browser,'POST','/v1/tom/requests',{...data,question:'Second'}),env,{})]);
 assert.equal(results.filter(r=>r.status==='fulfilled').length,1);assert.equal(results.filter(r=>r.status==='rejected')[0].reason.status,409);
 const saved=await db.prepare('SELECT payload_key FROM tom WHERE id=?').bind(data.request_id).first();const objects=(await bucket.list({prefix:`tom/${data.request_id}/`})).objects;assert.deepEqual(objects.map(o=>o.key),[saved.payload_key]);
});

test('conversation deletion checks every active turn and durably cleans more than 256 payloads',async()=>{
 const browser=await account('tom-history@example.invalid'),conversation=randomUUID(),env=localEnv();
 for(let n=0;n<257;n++){const requestId=randomUUID(),payloadKey=`tom/${requestId}/history.json`;await bucket.put(payloadKey,'{}');await db.prepare('INSERT INTO tom(id,user_id,conversation_id,fingerprint,payload,payload_key,status,created,updated) VALUES(?,?,?,?,?,?,?,?,?)').bind(requestId,browser.user,conversation,'x','{}',payloadKey,n===256?'streaming':'completed',n,n).run();}
 const url='/v1/tom/conversations/'+conversation;
 assert.equal((await (await route(directRequest(browser,'GET',url),env,{})).json()).turns.length,257,'history must not silently truncate');
 await assert.rejects(route(directRequest(browser,'DELETE',url),env,{}),/Stop active/);
 await db.prepare("UPDATE tom SET status='completed' WHERE conversation_id=?").bind(conversation).run();
 let removes=0;const interrupted=localEnv({UPLOADS:bucketWith({async delete(key){if(++removes===2)throw new Error('synthetic temporary object-store failure');return bucket.delete(key);}})});
 await assert.rejects(route(directRequest(browser,'DELETE',url),interrupted,{}),/temporary/);
 assert.ok((await db.prepare("SELECT COUNT(*) AS count FROM tom WHERE conversation_id=? AND status='deleting'").bind(conversation).first()).count>0,'cleanup intent survives interruption');
 await assert.rejects(route(directRequest(browser,'POST','/v1/tom/requests',{request_id:randomUUID(),conversation_id:conversation,scope:'general',question:'late retry',context:null,history:[],consent:true,provider:'openai',max_output_tokens:2048,model:'gpt-5.4-mini'}),env,{}),/deleted/);
 await sweep(env);
 assert.equal((await db.prepare('SELECT COUNT(*) AS count FROM tom WHERE conversation_id=?').bind(conversation).first()).count,0);
 assert.equal((await bucket.list({prefix:'tom/'})).objects.filter(o=>o.key.endsWith('/history.json')).length,0,'all 257 payloads removed after cleanup resumes');
});


test('Workers AI uses disclosed server binding, bounded vision messages and real internal SSE normalization',async()=>{
 const browser=await account('workers-ai@example.invalid'),model='@cf/meta/llama-4-scout-17b-16e-instruct',calls=[];
 const env=localEnv({TOM_PROVIDER:'workers-ai',TOM_MODELS:model,TOM_MAX_OUTPUT_TOKENS:'128',OPENAI_API_KEY:'',AI:{async run(selected,input,options){calls.push({selected,input,options});return new Response('data: {"response":"Cloudflare partial"}\n\ndata: {"choices":[{"delta":{"content":" answer"}}]}\n\ndata: [DONE]\n\n').body;}}});
 const cfg=await (await route(directRequest(browser,'GET','/v1/tom/config'),env,{})).json();assert.equal(cfg.provider.label,'Cloudflare Workers AI');assert.equal(cfg.configured,true);assert.deepEqual(cfg.models,[model]);assert.equal(cfg.max_output_tokens,128);
 const d={request_id:randomUUID(),conversation_id:randomUUID(),scope:'general',question:'Synthetic question',context:null,history:[],consent:true,provider:'workers-ai',max_output_tokens:128,model};
 await route(directRequest(browser,'POST','/v1/tom/requests',d),env,{});await processTom(env,d.request_id);await processTom(env,d.request_id);assert.equal(calls.length,1);assert.equal(calls[0].selected,model);assert.equal(calls[0].input.max_tokens,128);assert.equal(calls[0].input.stream,true);assert.equal(calls[0].input.tools,undefined);assert.ok(calls[0].options.signal instanceof AbortSignal);
 const row=await db.prepare('SELECT status,text,provider FROM tom WHERE id=?').bind(d.request_id).first();assert.deepEqual(row,{status:'completed',text:'Cloudflare partial answer',provider:'workers-ai'});
 const png='data:image/png;base64,'+Buffer.from([137,80,78,71,13,10,26,10]).toString('base64');const vision=workersAIPayload(validateTom({...d,question:'',purpose:'transcribe',handwriting_image:png,history:[{role:'user',text:'unrelated private history'}]},[model]),128);assert.deepEqual(vision.messages.at(-1).content.at(-1),{type:'image_url',image_url:{url:png}});assert.match(vision.messages.at(-1).content[0].text,/\[unclear\]/);assert.equal(vision.messages.length,2,'transcription has no unrelated document/history');
 assert.equal(decodeProviderEvent('workers-ai','{"response":"last partial","finish_reason":"length"}').incomplete,true);assert.equal(decodeProviderEvent('workers-ai','{"choices":[{"finish_reason":"stop"}]}').done,true);assert.equal(decodeProviderEvent('workers-ai','{"response":4}').delta,'4');assert.equal(decodeProviderEvent('workers-ai','{"response":false}').delta,'false');assert.throws(()=>decodeProviderEvent('workers-ai','{"response":{"text":"not a documented text delta"}}'),/type is invalid/);assert.equal(tomConfiguration({...env,TOM_ENABLED:'false'}).configured,false);
 const disabled={...env,TOM_PROVIDER:'unexpected'};assert.equal(tomConfiguration(disabled).configured,false);
});

test('Workers AI cancellation aborts pending inference and provider changes cannot silently reroute consent',async()=>{
 const browser=await account('workers-ai-cancel@example.invalid'),model='@cf/meta/llama-4-scout-17b-16e-instruct';let started=false,aborted=false;
 const env=localEnv({TOM_PROVIDER:'workers-ai',TOM_MODELS:model,TOM_MAX_OUTPUT_TOKENS:'128',OPENAI_API_KEY:'',AI:{async run(_model,_input,options){started=true;return new Promise((_,reject)=>options.signal.addEventListener('abort',()=>{aborted=true;reject(new Error('synthetic canceled provider'));},{once:true}));}}});
 const d={request_id:randomUUID(),conversation_id:randomUUID(),scope:'general',question:'Synthetic question',context:null,history:[],consent:true,provider:'workers-ai',max_output_tokens:128,model};await route(directRequest(browser,'POST','/v1/tom/requests',d),env,{});const processing=processTom(env,d.request_id);for(let n=0;n<100&&!started;n++)await new Promise(r=>setTimeout(r,10));assert.ok(started);await route(directRequest(browser,'POST',`/v1/tom/requests/${d.request_id}/cancel`,{}),env,{});await processing;assert.equal(aborted,true);assert.equal((await db.prepare('SELECT status FROM tom WHERE id=?').bind(d.request_id).first()).status,'canceled');
 const next={...d,request_id:randomUUID()};await route(directRequest(browser,'POST','/v1/tom/requests',next),env,{});await processTom({...env,TOM_PROVIDER:'openai',OPENAI_API_KEY:'synthetic'},next.request_id);const rejected=await db.prepare('SELECT status,error FROM tom WHERE id=?').bind(next.request_id).first();assert.equal(rejected.status,'interrupted');assert.match(rejected.error,/provider changed/i);
});

test('consent provider and output budget are enforced at POST and again before inference',async()=>{
 const browser=await account('consent-pinning@example.invalid'),queued=[],model='synthetic-shared-model';let calls=0;
 const env=localEnv({TOM_PROVIDER:'workers-ai',TOM_MODELS:model,TOM_MAX_OUTPUT_TOKENS:'128',AI:{async run(){calls++;throw new Error('Must not infer without matching consent');}},WORK:{async send(value){queued.push(value);}}});
 const original={request_id:randomUUID(),conversation_id:randomUUID(),scope:'general',question:'Synthetic consent race',context:null,history:[],consent:true,provider:'workers-ai',max_output_tokens:128,model};
 for(const change of [{provider:'openai'},{max_output_tokens:2048},{provider:undefined},{max_output_tokens:undefined}]){
  const d={...original,...change,request_id:randomUUID()};
  await assert.rejects(route(directRequest(browser,'POST','/v1/tom/requests',d),env,{}),/provider|limit/i);
  assert.equal(await db.prepare('SELECT id FROM tom WHERE id=?').bind(d.request_id).first(),null);
 }
 assert.equal(queued.length,0);assert.equal(calls,0);
 await route(directRequest(browser,'POST','/v1/tom/requests',original),env,{});assert.equal(queued.length,1);
 await processTom({...env,TOM_MAX_OUTPUT_TOKENS:'256'},original.request_id);
 assert.equal(calls,0);const result=await db.prepare('SELECT status,error FROM tom WHERE id=?').bind(original.request_id).first();assert.equal(result.status,'interrupted');assert.match(result.error,/response limit changed/i);
});
test('Tom read-and-answer: one request reads the handwriting, records what it read, then answers that text',async()=>{const browser=await account('readanswer@example.invalid'),work=[];const env={DB:db,UPLOADS:bucket,APP_ORIGIN:origin,ALLOW_LOCAL_HTTP:'true',TOM_MODELS:'gpt-5.4-mini',TOM_ENABLED:'true',OPENAI_API_KEY:'synthetic',WORK:{async send(value){work.push(value);}}};
 const png='data:image/png;base64,'+Buffer.from([137,80,78,71,13,10,26,10]).toString('base64'),context={document_id:randomUUID(),revision:'revision',anchor:{page:1},text:'The selected passage.'},history=[{role:'user',text:'An earlier question'},{role:'assistant',text:'An earlier answer'}];
 const data={request_id:randomUUID(),conversation_id:randomUUID(),scope:'sentences',question:'',context,history,handwriting_image:png,purpose:'read-answer',consent:true,provider:'openai',max_output_tokens:2048,model:'gpt-5.4-mini'};
 // The handwriting is required and is the whole question; scope rules are those of an answer.
 assert.throws(()=>validateTom({...data,handwriting_image:undefined},['gpt-5.4-mini']));assert.throws(()=>validateTom({...data,question:'typed as well'},['gpt-5.4-mini']),/handwritten question only/);assert.throws(()=>validateTom({...data,scope:'general'},['gpt-5.4-mini']));
 // The capability is a response header: the config body keeps exactly the keys readers already check strictly.
 const config=await route(directRequest(browser,'GET','/v1/tom/config'),env,{});assert.equal(config.headers.get('X-Inkbound-Tom-Mixed-Reply'),'1');assert.equal(config.headers.get('X-Inkbound-Tom-Purposes'),'answer,transcribe,read-answer,ink-plan');assert.deepEqual(Object.keys(await config.json()).sort(),['configured','daily_limit','max_output_tokens','models','provider']);
 // One request from the reader, counted as two daily attempts (two provider calls).
 const count=async()=>(await db.prepare('SELECT count FROM limits WHERE bucket=?').bind('tom:'+browser.user).first())?.count||0;const before=await count();assert.equal((await route(directRequest(browser,'POST','/v1/tom/requests',data),env,{})).status,202);assert.equal(work.length,1);assert.equal(await count()-before,2);
 const sse=(...parts)=>new Response(parts.map(p=>'data: '+JSON.stringify(p)+'\n\n').join(''),{headers:{'Content-Type':'text/event-stream'}});const calls=[],savedFetch=globalThis.fetch;
 try{globalThis.fetch=async(url,init)=>{assert.equal(url,'https://api.openai.com/v1/responses');calls.push(JSON.parse(init.body));return calls.length===1?sse({type:'response.output_text.delta',delta:'What does '},{type:'response.output_text.delta',delta:'this mean?'},{type:'response.completed'}):sse({type:'response.output_text.delta',delta:'It means the passage says this.'},{type:'response.completed'});};await processTom(env,data.request_id);await processTom(env,data.request_id);}finally{globalThis.fetch=savedFetch;}
 assert.equal(calls.length,2,'one read and one answer; a redelivered queue job sends nothing more');const texts=b=>b.input.at(-1).content.filter(c=>c.type==='input_text').map(c=>c.text).join('\n'),images=b=>b.input.at(-1).content.filter(c=>c.type==='input_image').length;
 // The read is the transcription prompt over the handwriting only: no passage, no history.
 assert.match(texts(calls[0]),/^Transcribe the handwritten question/);assert.equal(calls[0].input.length,1);assert.equal(images(calls[0]),1);assert.ok(!texts(calls[0]).includes('selected passage'));
 // The answer is an ordinary answer to the text that was read, with the passage and history and no image.
 assert.ok(texts(calls[1]).startsWith('Question: What does this mean?'));assert.ok(texts(calls[1]).includes('The selected passage.'));assert.equal(calls[1].input.length,3);assert.equal(images(calls[1]),0);
 const row=await db.prepare('SELECT status,text FROM tom WHERE id=?').bind(data.request_id).first();assert.equal(row.status,'completed');assert.equal(row.text,'It means the passage says this.');
 const events=(await db.prepare('SELECT event,data FROM tom_events WHERE request_id=? ORDER BY seq').bind(data.request_id).all()).results,asked=events.filter(e=>e.event==='question');assert.equal(asked.length,1);assert.deepEqual(JSON.parse(asked[0].data),{text:'What does this mean?'});assert.ok(events.findIndex(e=>e.event==='question')<events.findIndex(e=>e.event==='delta'),'what was read arrives before the answer');
 // Unreadable handwriting: no answer call, no answer text, a terminal error the reader can retry explicitly.
 const blank={...data,request_id:randomUUID()};assert.equal((await route(directRequest(browser,'POST','/v1/tom/requests',blank),env,{})).status,202);calls.length=0;
 try{globalThis.fetch=async(url,init)=>{calls.push(JSON.parse(init.body));return sse({type:'response.output_text.delta',delta:' [unclear] '},{type:'response.completed'});};await processTom(env,blank.request_id);}finally{globalThis.fetch=savedFetch;}
 assert.equal(calls.length,1);const failed=await db.prepare('SELECT status,text,error FROM tom WHERE id=?').bind(blank.request_id).first();assert.equal(failed.status,'interrupted');assert.ok(!failed.text);assert.match(failed.error,/could not be read/);assert.equal((await db.prepare("SELECT COUNT(*) AS n FROM tom_events WHERE request_id=? AND event='question'").bind(blank.request_id).first()).n,0);
});


test('daily usage ceilings are configuration: defaults stay, custom values apply, unlimited removes them',async()=>{
assert.equal(dailyCap(undefined,30),30);assert.equal(dailyCap('',30),30);assert.equal(dailyCap('unlimited',30),0);assert.equal(dailyCap(' Unlimited ',10),0);assert.equal(dailyCap('0',10),0);assert.equal(dailyCap('500',30),500);for(const bad of ['abc','-5','1e9','12.5','99999999'])assert.equal(dailyCap(bad,30),30,bad);
 const ask=()=>({request_id:randomUUID(),conversation_id:randomUUID(),provider:'openai',model:'gpt-5.4-mini',max_output_tokens:2048,question:'Hello',scope:'general',context:null,history:[],consent:true,purpose:'answer'});
 const question=async(browser,env)=>{const d=ask();try{return await route(directRequest(browser,'POST','/v1/tom/requests',d),env,{});}finally{await db.prepare("UPDATE tom SET status='completed' WHERE id=?").bind(d.request_id).run();}}; /* completed between requests, so only the daily ceiling (not concurrency) can refuse */
 let n=0;for(const [limit,accepted] of [[undefined,30],['3',3]]){const browser=await account(`daily-cap-${n++}@example.invalid`),env=localEnv(limit===undefined?{}:{TOM_DAILY_LIMIT:limit});for(let i=0;i<accepted;i++)assert.equal((await question(browser,env)).status,202,String(i));await assert.rejects(question(browser,env),/Request limit reached/);}
 {const browser=await account('daily-cap-unlimited@example.invalid'),env=localEnv({TOM_DAILY_LIMIT:'unlimited'});for(let i=0;i<40;i++)assert.equal((await question(browser,env)).status,202,String(i));}
 const image=async(browser,env)=>route(directRequest(browser,'POST','/v1/tom/illustrations',{request_id:randomUUID(),prompt:'A small color castle',preset:'quick',provider:'openai',model:'gpt-image-1',consent:true}),env,{});
 {const browser=await account('image-cap-default@example.invalid'),env=localEnv({TOM_IMAGE_MODEL:'gpt-image-1'});for(let i=0;i<10;i++)assert.equal((await image(browser,env)).status,202,String(i));await assert.rejects(image(browser,env),/Request limit reached/);}
 {const browser=await account('image-cap-unlimited@example.invalid'),env=localEnv({TOM_IMAGE_MODEL:'gpt-image-1',TOM_IMAGE_DAILY_LIMIT:'unlimited'});for(let i=0;i<14;i++)assert.equal((await image(browser,env)).status,202,String(i));}
});

