 const provider={async generate(request,signal){++calls;assert.equal(request.model,'gpt-image-1');assert.match(request.prompt,/No letters/);assert.equal(signal.aborted,false);return bytes;}};
 await Promise.all([processIllustration(env,requestId,provider),processIllustration(env,requestId,provider)]);assert.equal(calls,1);
