 const content=await route(directRequest(browser,'GET',`/v1/tom/illustrations/${requestId}/content`),env,{});assert.equal(content.headers.get('content-type'),'image/png');assert.deepEqual(Buffer.from(await content.arrayBuffer()),bytes);
 await route(directRequest(browser,'POST',`/v1/tom/illustrations/${requestId}/cancel`,{}),env,{});assert.equal((await bucket.list({prefix:`tom-illustrations/${requestId}/`})).objects.length,0);
 await assert.rejects(route(directRequest(browser,'GET',`/v1/tom/illustrations/${requestId}/content`),env,{}),/not available/);
