test('workerd picture ranges preserve sealed SHA, resume identity and legacy full GET',async()=>{
 const browser=await account('picture-ranges@example.invalid'),other=await account('picture-ranges-other@example.invalid'),id=randomUUID(),key=`tom-illustrations/${id}/image.png`,bytes=Buffer.alloc(2300000,17),sha=digest(bytes),time=Date.now()/1000;
 await db.prepare("INSERT INTO tom_illustrations(id,user_id,fingerprint,prompt,provider,model,preset,status,created,updated,expires,object_key) VALUES(?,?,'fixture','','openai','gpt-image-1','quick','completed',?,?,?,?)").bind(id,browser.user,time,time,time+3600,key).run();
 for(const metadata of [undefined,{sha256:sha}]){
  await bucket.put(key,bytes,metadata?{customMetadata:metadata}:{});
  const path=`/v1/tom/illustrations/${id}/content`;const full=await browser.call('GET',path);assert.deepEqual(Buffer.from(full.result),bytes);assert.equal(full.headers.get('x-content-sha256'),sha);assert.equal(full.headers.get('etag'),'"'+sha+'"');
  const pieces=[];for(let start=0;start<bytes.length;start+=262144){const end=Math.min(start+262143,bytes.length-1),part=await browser.call('GET',path,undefined,undefined,{Range:`bytes=${start}-${end}`,'If-Match':'"'+sha+'"'},206);assert.equal(part.headers.get('content-range'),`bytes ${start}-${end}/${bytes.length}`);assert.equal(part.headers.get('content-length'),String(end-start+1));pieces.push(Buffer.from(part.result));}assert.equal(digest(Buffer.concat(pieces)),sha);
  for(const range of ['bytes=-10','bytes=1-0','bytes=2300000-','bytes=0-1,4-5','bytes=9007199254740992-']){const rejected=await browser.call('GET',path,undefined,undefined,{Range:range},416);assert.equal(rejected.headers.get('content-range'),'bytes */2300000');}
  const tail=await browser.call('GET',path,undefined,undefined,{Range:'bytes=2299990-'},206);assert.equal(tail.result.length,10);
  await browser.call('GET',path,undefined,undefined,{Range:'bytes=0-9','If-Match':'"'+('0'.repeat(64))+'"'},412);await other.call('GET',path,undefined,undefined,{Range:'bytes=0-9'},404);
 }
 await db.prepare("UPDATE tom_illustrations SET status='canceled' WHERE id=?").bind(id).run();await browser.call('GET',`/v1/tom/illustrations/${id}/content`,undefined,undefined,{Range:'bytes=0-9'},409);
});

