function visualPng(width=1536,height=1024){function chunk(type,data){const name=Buffer.from(type),b=Buffer.alloc(12+data.length);b.writeUInt32BE(data.length);name.copy(b,4);data.copy(b,8);let crc=0xffffffff;for(const byte of Buffer.concat([name,data])){crc^=byte;for(let k=0;k<8;k++)crc=(crc>>>1)^((crc&1)?0xedb88320:0);}b.writeUInt32BE((crc^0xffffffff)>>>0,b.length-4);return b;}const h=Buffer.alloc(13);h.writeUInt32BE(width);h.writeUInt32BE(height,4);h[8]=8;h[9]=6;const scan=Buffer.alloc((width*4+1)*height,255);for(let y=0;y<height;y++)scan[y*(width*4+1)]=0;return Buffer.concat([Buffer.from([137,80,78,71,13,10,26,10]),chunk('IHDR',h),chunk('IDAT',deflateSync(scan)),chunk('IEND',Buffer.alloc(0))]);}
