test('v4 advice too large to seal keeps the generated image with summary/issues but no locations, and makes no extra call',async()=>{
 const {validatePictureAdvice}=await import('../src/picture_review.mjs');const {transportPng}=await import('./picture_fixture.mjs');const browser=await account('picture-seal-fallback@example.invalid'),env=pictureEnv(),spec=await pictureSpec(),parent=await completedPictureParent(browser,env,spec),d=await pictureChild(browser,env,spec,parent,parent.question);
 const ring=(cx,cy,r)=>Array.from({length:64},(_,i)=>[cx+r*Math.cos(2*Math.PI*i/64+.1),cy+r*Math.sin(2*Math.PI*i/64+.1)]);const wide=(prefix,n)=>prefix+'\u6f22'.repeat(n-prefix.length); /* 3-byte UTF-8 text: the review limit counts characters, the envelope limit counts bytes */
 const issues=Array.from({length:32},(_,i)=>wide(`Synthetic issue ${i}: `,512));const make=holes=>({summary:wide('Synthetic oversized transport advice ',512),issues,components:spec.components.map(c=>({id:c.id,visible:true,confidence:.95,bounds:[0,0,1,1],target:[.5,.5],colors:[],geometry:{kind:'area',points:ring(.5,.5,.45),holes:Array.from({length:holes},(_,k)=>ring(.15+.1*k,.2,.03))},evidence:wide('Synthetic transport geometry, not quality evidence ',512)}))});
 let advice=make(0);for(let h=1;h<=8&&JSON.stringify(make(h)).length<=127000;h++)advice=make(h);
validatePictureAdvice(advice,d.visual_plan);assert.ok(JSON.stringify(advice).length<=128000,'control must pass the review character limit');assert.ok(Buffer.byteLength(JSON.stringify(advice))>128*1024,'control must exceed the envelope byte bound');await route(directRequest(browser,'POST','/v1/tom/illustrations',d),env,{});const calls=[],old=globalThis.fetch;
 try{globalThis.fetch=async(url)=>{calls.push(url);return url.endsWith('/images/generations')?Response.json({data:[{b64_json:transportPng().toString('base64')}]}):Response.json({status:'completed',output:[{type:'message',content:[{type:'output_text',text:JSON.stringify(advice)}]}]});};await processIllustration(env,d.request_id);await processIllustration(env,d.request_id);}finally{globalThis.fetch=old;}
 assert.deepEqual(calls,['https://api.openai.com/v1/images/generations','https://api.openai.com/v1/responses']);const status=await (await route(directRequest(browser,'GET','/v1/tom/illustrations/'+d.request_id),env,{})).json();assert.equal(status.status,'completed');assert.equal(status.quality_status,'unverified');assert.equal(status.review.status,'advisory');assert.equal(status.review.sealing,'fallback');assert.deepEqual(status.review.issues,issues);
 const meta=envelopeOf(Buffer.from(await (await route(directRequest(browser,'GET',`/v1/tom/illustrations/${d.request_id}/content`),env,{})).arrayBuffer()));assert.equal(meta.grounding_status,'unbound');assert.equal(meta.advice.components.length,spec.components.length);assert.ok(meta.advice.components.every(g=>g.bounds===null&&g.target===null&&g.geometry===null));assert.equal(meta.parent_request_id,parent.request_id);
});
test('v4 cancel racing the advisory review never publishes the image or repeats inference',async()=>{
 const {transportPng}=await import('./picture_fixture.mjs');const browser=await account('picture-cancel-review@example.invalid'),env=pictureEnv(),spec=await pictureSpec(),parent=await completedPictureParent(browser,env,spec),d=await pictureChild(browser,env,spec,parent,parent.question);await route(directRequest(browser,'POST','/v1/tom/illustrations',d),env,{});const calls=[],old=globalThis.fetch;
 try{globalThis.fetch=async(url)=>{calls.push(url);if(url.endsWith('/images/generations'))return Response.json({data:[{b64_json:transportPng().toString('base64')}]});await route(directRequest(browser,'POST',`/v1/tom/illustrations/${d.request_id}/cancel`,{}),env,{});return Response.json({status:'completed',output:[{type:'message',content:[{type:'output_text',text:JSON.stringify({summary:'Synthetic advice',issues:[],components:[]})}]}]});};await processIllustration(env,d.request_id);await processIllustration(env,d.request_id);}finally{globalThis.fetch=old;}
 assert.equal(calls.length,2);assert.equal((await db.prepare('SELECT status FROM tom_illustrations WHERE id=?').bind(d.request_id).first()).status,'canceled');assert.equal((await bucket.list({prefix:`tom-illustrations/${d.request_id}/`})).objects.length,0);await assert.rejects(route(directRequest(browser,'GET',`/v1/tom/illustrations/${d.request_id}/content`),env,{}),/not available/);
});
test('sweep cancels orphaned picture children and removes their image before expiry',async()=>{
 const {transportPng}=await import('./picture_fixture.mjs');const browser=await account('picture-orphan@example.invalid'),env=pictureEnv(),spec=await pictureSpec(),parent=await completedPictureParent(browser,env,spec),d=await pictureChild(browser,env,spec,parent,parent.question);await route(directRequest(browser,'POST','/v1/tom/illustrations',d),env,{});const old=globalThis.fetch;
 try{globalThis.fetch=async(url)=>url.endsWith('/images/generations')?Response.json({data:[{b64_json:transportPng().toString('base64')}]}):Response.json({},{status:503});await processIllustration(env,d.request_id);}finally{globalThis.fetch=old;}
 assert.equal((await db.prepare('SELECT status FROM tom_illustrations WHERE id=?').bind(d.request_id).first()).status,'completed');assert.equal((await bucket.list({prefix:`tom-illustrations/${d.request_id}/`})).objects.length,1);
 await db.prepare('DELETE FROM tom WHERE id=?').bind(parent.request_id).run(); /* simulates an interrupted cleanup or out-of-band removal; the API itself always cleans children first */
 await sweep({DB:db,UPLOADS:bucket,WORK:{async send(){}}});assert.equal((await db.prepare('SELECT status FROM tom_illustrations WHERE id=?').bind(d.request_id).first()).status,'canceled');assert.equal((await bucket.list({prefix:`tom-illustrations/${d.request_id}/`})).objects.length,0);
});
test('v4 illustration diagnostics correlate child, parent, schema and plan hash without prompts or credentials',async()=>{
 const {transportPng}=await import('./picture_fixture.mjs');const browser=await account('picture-trace@example.invalid'),env={...pictureEnv(),TOM_DIAGNOSTICS:'true'},spec=await pictureSpec(),parent=await completedPictureParent(browser,env,spec),d=await pictureChild(browser,env,spec,parent,parent.question);await route(directRequest(browser,'POST','/v1/tom/illustrations',d),env,{});const lines=[],old=globalThis.fetch,log=console.log;
 try{console.log=(...a)=>{lines.push(a.join(' '));};globalThis.fetch=async(url)=>url.endsWith('/images/generations')?Response.json({data:[{b64_json:transportPng().toString('base64')}]}):Response.json({},{status:503});await processIllustration(env,d.request_id);}finally{globalThis.fetch=old;console.log=log;}
 const events=lines.filter(l=>l.includes('"intent":"illustration"')).map(l=>JSON.parse(l));assert.deepEqual(events.map(e=>e.status),['started','completed']);for(const e of events){assert.equal(e.request_id,d.request_id);assert.equal(e.parent_request_id,parent.request_id);assert.equal(e.schema_version,4);assert.equal(e.scene_sha256,d.plan_sha256);}
 const all=lines.join('\n');assert.ok(!all.includes('synthetic')&&!all.includes(d.prompt.slice(0,40))&&!all.includes('iVBOR'),'no credential, prompt or image bytes in diagnostics');
});

test('registered periodic-table requests use exact reference facts through real D1/R2 and durable SSE',async()=>{
 const browser=await account('reference-table@example.invalid'),env=localEnv({TOM_IMAGE_MODEL:'gpt-image-2.5-flare',TOM_SCENE_MAX_OUTPUT_TOKENS:'16384',TOM_SCENE_REQUEST_VERSION:'4'}),question='In great! Wanted to see if you can draw out a periodic table for me?';
 for(const reading of [false,true]){const data={request_id:randomUUID(),conversation_id:randomUUID(),provider:'openai',model:'gpt-5.4-mini',max_output_tokens:16384,question:reading?'':question,scope:'general',context:null,history:[],consent:true,purpose:reading?'read-auto-scene-answer':'auto-scene-answer',illustration_model:env.TOM_IMAGE_MODEL,scene_version:4,...(reading?{handwriting_image:'data:image/png;base64,iVBORw0KGgo='}:{})};assert.equal((await route(directRequest(browser,'POST','/v1/tom/requests',data),env,{})).status,202);const original=globalThis.fetch;let calls=0;try{globalThis.fetch=async(url,init)=>{++calls;assert.ok(reading);const body=JSON.parse(init.body);assert.match(body.input.at(-1).content[0].text,/^Transcribe/);return new Response('data: '+JSON.stringify({type:'response.output_text.delta',delta:question})+'\n\ndata: '+JSON.stringify({type:'response.completed'})+'\n\n');};await processTom(env,data.request_id);await processTom(env,data.request_id);}finally{globalThis.fetch=original;}assert.equal(calls,reading?1:0,'only handwriting reading needs inference; queue redelivery is inert');const row=await db.prepare('SELECT status,text,error FROM tom WHERE id=?').bind(data.request_id).first();assert.equal(row.status,'completed',row.error);const reply=JSON.parse(row.text);assert.equal(reply.visual.datasets[0].rows.length,118);assert.equal(reply.visual.datasets[0].source,'reference:chemical-elements-2022');const {validateVisualSources}=await import('../src/visual_sources.mjs');validateVisualSources(reply.visual,question);const events=(await db.prepare('SELECT event,data FROM tom_events WHERE request_id=? ORDER BY seq').bind(data.request_id).all()).results;assert.equal(events.filter(e=>e.event==='question').length,reading?1:0);assert.equal(events.filter(e=>e.event==='delta').map(e=>JSON.parse(e.data).text).join(''),row.text);assert.equal(JSON.parse(events.at(-1).data).status,'completed');}
});

test('terminal cleanup cannot resurrect a canceled conversation whose payload cleanup is pending',async()=>{
 const browser=await account('tom-delete-finalize@example.invalid'),env=localEnv({TOM_IMAGE_MODEL:'gpt-image-2.5-flare',TOM_SCENE_MAX_OUTPUT_TOKENS:'16384',TOM_SCENE_REQUEST_VERSION:'4'}),data={request_id:randomUUID(),conversation_id:randomUUID(),provider:'openai',model:'gpt-5.4-mini',max_output_tokens:16384,question:'Draw the periodic table.',scope:'general',context:null,history:[],consent:true,purpose:'auto-scene-answer',illustration_model:env.TOM_IMAGE_MODEL,scene_version:4};
 assert.equal((await route(directRequest(browser,'POST','/v1/tom/requests',data),env,{})).status,202);
 let enter,release;const entered=new Promise(resolve=>{enter=resolve;}),gate=new Promise(resolve=>{release=resolve;});
 const delayed=new Proxy(bucket,{get(target,key){if(key==='get')return async(...args)=>{enter();await gate;return target.get(...args);};const value=Reflect.get(target,key);return typeof value==='function'?value.bind(target):value;}});
 const processing=processTom({...env,UPLOADS:delayed},data.request_id);
 await entered;
 try{assert.equal((await route(directRequest(browser,'POST',`/v1/tom/requests/${data.request_id}/cancel`,{}),env,{})).status,200);const failing=new Proxy(bucket,{get(target,key){if(key==='delete')return async()=>{throw Error('synthetic retained cleanup failure');};const value=Reflect.get(target,key);return typeof value==='function'?value.bind(target):value;}});await assert.rejects(route(directRequest(browser,'DELETE',`/v1/tom/conversations/${data.conversation_id}`),{...env,UPLOADS:failing},{}),/synthetic retained cleanup failure/);}finally{release();}
 const eventsBefore=(await db.prepare('SELECT COUNT(*) AS n FROM tom_events WHERE request_id=?').bind(data.request_id).first()).n;
 await processing;
 const retained=await db.prepare('SELECT status,text FROM tom WHERE id=?').bind(data.request_id).first();assert.equal(retained.status,'deleting');assert.equal(retained.text,'');assert.equal((await db.prepare('SELECT COUNT(*) AS n FROM tom_events WHERE request_id=?').bind(data.request_id).first()).n,eventsBefore);
 const listed=await (await route(directRequest(browser,'GET','/v1/tom/conversations'),env,{})).json();assert.ok(!listed.conversations.some(c=>c.conversation_id===data.conversation_id));
 assert.equal((await route(directRequest(browser,'DELETE',`/v1/tom/conversations/${data.conversation_id}`),env,{})).status,200);assert.equal(await db.prepare('SELECT id FROM tom WHERE id=?').bind(data.request_id).first(),null);
});
test('a version 5 color follow-up redraws the registered table in color from the catalog without a provider call; version 4 still asks the planner',async()=>{
 const browser=await account('color-followup@example.invalid'),drawn=[{role:'user',text:'Draw the periodic table'},{role:'assistant',text:'Chemical elements, IUPAC 4 May 2022\nchemical-elements-2022: 118 records'}];
 const offered=[...drawn,{role:'user',text:'Add color'},{role:'assistant',text:'Do you want me to color the periodic table by element category, such as alkali metals, noble gases, and so on? If so, I can do that, but I need the coloring rule you want.'}];
 for(const [version,reading,question,history] of [[5,false,'Add color',drawn],[5,true,'Yes',offered],[4,false,'Add color',drawn]]){
  const env=localEnv({TOM_IMAGE_MODEL:'gpt-image-2.5-flare',TOM_SCENE_MAX_OUTPUT_TOKENS:'16384',TOM_SCENE_REQUEST_VERSION:String(version)});
  const data={request_id:randomUUID(),conversation_id:randomUUID(),provider:'openai',model:'gpt-5.4-mini',max_output_tokens:16384,question:reading?'':question,scope:'general',context:null,history,consent:true,purpose:reading?'read-auto-scene-answer':'auto-scene-answer',illustration_model:env.TOM_IMAGE_MODEL,scene_version:version,...(reading?{handwriting_image:'data:image/png;base64,iVBORw0KGgo='}:{})};
  assert.equal((await route(directRequest(browser,'POST','/v1/tom/requests',data),env,{})).status,202);
  const original=globalThis.fetch;let calls=0;try{globalThis.fetch=async(url,init)=>{++calls;const transcribing=/^Transcribe/.test(JSON.parse(init.body).input.at(-1).content[0].text);const delta=transcribing?question:JSON.stringify({mode:'text',response:'Which coloring rule would you like?',visual:null});return new Response('data: '+JSON.stringify({type:'response.output_text.delta',delta})+'\n\ndata: '+JSON.stringify({type:'response.completed'})+'\n\n');};await processTom(env,data.request_id);}finally{globalThis.fetch=original;}
  const row=await db.prepare('SELECT status,text,error FROM tom WHERE id=?').bind(data.request_id).first();assert.equal(row.status,'completed',row.error);const reply=JSON.parse(row.text);
  if(version===5){assert.equal(calls,reading?1:0,'only reading the handwriting needs inference');assert.equal(reply.visual.palette.length,12);assert.equal(reply.visual.datasets[0].source,'reference:chemical-elements-2022');assert.equal(reply.visual.datasets[0].rows.length,118);}
  else{assert.equal(calls,1);assert.equal(reply.mode,'text');}
 }
});
test('an image provider refusal keeps OpenAI\'s reason on the illustration (status, code, short message), never the key',async()=>{
 const {OpenAIImageProvider}=await import('../src/illustrations.mjs'),{need,bodyBytes}=await import('../src/worker.mjs');
 const browser=await account('image-refusal@example.invalid'),env=localEnv({TOM_IMAGE_MODEL:'gpt-image-1'});
 const create=async()=>{const id=randomUUID();await route(directRequest(browser,'POST','/v1/tom/illustrations',{request_id:id,prompt:'A small color castle',preset:'quick',provider:'openai',model:'gpt-image-1',consent:true}),env,{});return id;};
 const refused=await create(),provider=new OpenAIImageProvider({OPENAI_API_KEY:'synthetic',TOM_IMAGE_MODEL:'gpt-image-1'},need,bodyBytes,async()=>new Response(JSON.stringify({error:{message:'Your organization must be verified to use the model `gpt-image-1`. Please go to: https://platform.openai.com/settings/organization/general and click on Verify Organization. (sk-proj-abcdef123456)',type:'invalid_request_error',param:null,code:null}}),{status:403,headers:{'Content-Type':'application/json'}}));
 await processIllustration(env,refused,provider);
 const result=await (await route(directRequest(browser,'GET','/v1/tom/illustrations/'+refused),env,{})).json();
 assert.equal(result.status,'interrupted');assert.match(result.error,/verified OpenAI organization \(OpenAI 403 invalid_request_error\)/);assert.doesNotMatch(result.error,/sk-|synthetic/);
 const broken=await create();await processIllustration(env,broken,{async generate(){throw new Error('unexpected local failure');}});
 assert.equal((await (await route(directRequest(browser,'GET','/v1/tom/illustrations/'+broken),env,{})).json()).error,'Tom could not generate that illustration. Retry explicitly.'); /* other failures keep the generic text */
});

test('current delivery scope excludes historical jobs and other accounts in actual D1',async()=>{
 const owner=await account('scoped-delivery@example.test'),peer=await account('scoped-peer@example.test');const reader=await pair(owner);const jobs=[];
 for(let i=0;i<3;++i){const created=await owner.call('POST','/v1/jobs',{device_id:reader.device_id||reader.id,filename:`payload-${i}.pdf`,size:19,sha256:digest(Buffer.from('synthetic payload '+i)),new_import:true},undefined,{},201);jobs.push(created.result.job_id);}
 const latest=(await owner.call('GET','/v1/jobs?limit=1')).result.jobs;assert.equal(latest.length,1);
 const chosen=(await owner.call('GET','/v1/jobs?ids='+jobs[1])).result.jobs;assert.deepEqual(chosen.map(j=>j.job_id),[jobs[1]]);
 assert.deepEqual((await peer.call('GET','/v1/jobs?ids='+jobs[1])).result.jobs,[]);
 await owner.call('GET','/v1/jobs?ids=invalid',undefined,undefined,{},400);
});

test('native polling excludes rejected older payloads without canceling or acknowledging them',async()=>{const owner=await account('paused-native@example.test'),native=await pair(owner),ids=[];const t=Date.now()/1000;for(let i=0;i<9;++i){const result=(await owner.call('POST','/v1/jobs',{device_id:native.id,filename:`native-${i}.pdf`,size:19,sha256:digest(Buffer.from('synthetic payload '+i)),new_import:true},undefined,{},201)).result;ids.push(result.job_id);await db.prepare("UPDATE jobs SET status='waiting for device',format='pdf',size=source_size,sha256=source_sha256,created=? WHERE id=?").bind(t+i,result.job_id).run();}const before=(await native.call('GET','/v1/device/jobs')).result.jobs;assert.equal(before.length,8);assert(!before.some(j=>j.job_id===ids[8]));const current=(await native.call('GET','/v1/device/jobs?exclude='+ids.slice(0,8).join(','))).result.jobs;assert.deepEqual(current.map(j=>j.job_id),[ids[8]]);const retained=await db.prepare('SELECT status FROM jobs WHERE id=?').bind(ids[0]).first();assert.equal(retained.status,'waiting for device');await native.call('GET','/v1/device/jobs?exclude=bad',undefined,undefined,{},400);});


test('durable canceled delivery reports terminal identity without resurrection and keeps later queue jobs',async()=>{
 const owner=await account('canceled-durable@example.test'),native=await pair(owner),source=Buffer.from('synthetic canceled PDF bytes'),sha=digest(source);
 const first=(await owner.call('POST','/v1/jobs',{device_id:native.id,filename:'first.pdf',size:source.length,sha256:sha,new_import:true},undefined,{},201)).result;
 await db.prepare("UPDATE jobs SET status='canceled',format='pdf',size=source_size,sha256=source_sha256 WHERE id=?").bind(first.job_id).run();
 const row=await db.prepare('SELECT document_id FROM jobs WHERE id=?').bind(first.job_id).first();
 const ack={document_id:row.document_id,sha256:sha,durable:true};
 await native.call('POST',`/v1/device/jobs/${first.job_id}/ack`,{...ack,sha256:'0'.repeat(64)},undefined,{},409);
 const terminal=(await native.call('POST',`/v1/device/jobs/${first.job_id}/ack`,ack)).result;
 assert.deepEqual(terminal,{status:'canceled',terminal:true,job_id:first.job_id,document_id:row.document_id,sha256:sha});
 assert.equal((await db.prepare('SELECT status FROM jobs WHERE id=?').bind(first.job_id).first()).status,'canceled');
 const unfinished=(await owner.call('POST','/v1/jobs',{device_id:native.id,filename:'unfinished.pdf',size:source.length,sha256:sha,new_import:true},undefined,{},201)).result;
 await db.prepare("UPDATE jobs SET status='canceled' WHERE id=?").bind(unfinished.job_id).run();const pending=await db.prepare('SELECT document_id FROM jobs WHERE id=?').bind(unfinished.job_id).first();await native.call('POST',`/v1/device/jobs/${unfinished.job_id}/ack`,{document_id:pending.document_id,sha256:null,durable:true},undefined,{},409);
 const later=(await owner.call('POST','/v1/jobs',{device_id:native.id,filename:'later.pdf',size:source.length,sha256:sha,new_import:true},undefined,{},201)).result;
 await db.prepare("UPDATE jobs SET status='waiting for device',format='pdf',size=source_size,sha256=source_sha256 WHERE id=?").bind(later.job_id).run();
 assert.deepEqual((await native.call('GET','/v1/device/jobs')).result.jobs.map(j=>j.job_id),[later.job_id]);
 const other=await pair(owner);await other.call('POST',`/v1/device/jobs/${first.job_id}/ack`,ack,undefined,{},404);
});
